insert into tax_fact_definition (id, label, kind, unit, owner, help, evidence, choices) values
    ('net_weight_oz', 'Net weight (oz)', 'DECIMAL', 'oz', 'VARIANT', 'The net weight of one package in ounces, as printed on the label.', false, '[]'::jsonb),
    ('servings_per_package', 'Servings per package', 'INTEGER', null, 'VARIANT', 'How many servings the label says one package holds.', false, '[]'::jsonb),
    ('individual_serving', 'Sold as a single serving', 'BOOLEAN', null, 'VARIANT', 'Yes if the package is one portion meant for one person at one time.', false, '[]'::jsonb),
    ('is_candy', 'Candy or confectionery', 'BOOLEAN', null, 'VARIANT', 'Yes if this is candy, chocolate, gum or a sweet confection. Candy is taxed at any size.', false, '[]'::jsonb),
    ('candy_coated', 'Coated or sugar-glazed', 'BOOLEAN', null, 'VARIANT', 'Yes if the nuts or seeds are candy-coated, chocolate-covered, honey-glazed or otherwise confectionery.', false, '[]'::jsonb),
    ('sold_heated', 'Sold hot or heated', 'BOOLEAN', null, 'OFFER', 'Yes if you serve or sell this warm, or warm it before the customer gets it.', false, '[]'::jsonb),
    ('heated_by_seller', 'You heat it', 'BOOLEAN', null, 'OFFER', 'Yes if you (not the customer) do the heating.', false, '[]'::jsonb),
    ('utensils_provided', 'You provide eating utensils', 'BOOLEAN', null, 'OFFER', 'Yes if forks, spoons, straws or plates for eating it are included with the order.', false, '[]'::jsonb),
    ('seller_is_bakery', 'Your shop is a bakery', 'BOOLEAN', null, 'SELLER', 'Taken from your seller profile: yes if your business is a bakery.', false, '[]'::jsonb),
    ('prepared_meal', 'Sold as a prepared meal', 'BOOLEAN', null, 'VARIANT', 'Yes if it is ready to eat as a meal (cooked and portioned), not raw or for cooking at home.', false, '[]'::jsonb),
    ('cooked_hot', 'Sold cooked and hot', 'BOOLEAN', null, 'OFFER', 'Yes if you sell it freshly cooked and hot.', false, '[]'::jsonb),
    ('juice_percent', 'Fruit or vegetable juice content', 'PERCENT', '%', 'VARIANT', 'The percentage of real fruit or vegetable juice, as stated on the label.', false, '[]'::jsonb),
    ('sweetened', 'Sweetened', 'BOOLEAN', null, 'VARIANT', 'Yes if sugar, syrup, honey or another sweetener is added.', false, '[]'::jsonb),
    ('soft_drink', 'Classified as a soft drink', 'BOOLEAN', null, 'VARIANT', 'Yes if it is a carbonated or sweetened drink in the soft-drink style (soda, sports or energy drink).', false, '[]'::jsonb),
    ('contains_milk', 'Contains milk or a milk substitute', 'BOOLEAN', null, 'VARIANT', 'Yes if milk, cream or a plant milk (oat, soy, almond...) is an ingredient.', false, '[]'::jsonb),
    ('label_type', 'Label on the package', 'CHOICE', null, 'VARIANT', 'The panel printed on the package: Drug Facts, Supplement Facts or Nutrition Facts.', false, '[{"value":"DRUG_FACTS","label":"Drug Facts"},{"value":"SUPPLEMENT_FACTS","label":"Supplement Facts"},{"value":"NUTRITION_FACTS","label":"Nutrition Facts"},{"value":"NONE","label":"No such label"}]'::jsonb),
    ('qualifying_label', 'Qualifies as a labelled drug or supplement', 'BOOLEAN', null, 'VARIANT', 'Yes only if the label is on the package and the product fits that label''s definition. Our tax team checks this.', false, '[]'::jsonb),
    ('label_evidence', 'Photo or PDF of the label', 'FILE', null, 'VARIANT', 'Upload a clear picture of the whole label. It is kept as the proof for the exemption.', true, '[]'::jsonb),
    ('hygiene_kind', 'Kind of hygiene product', 'CHOICE', null, 'VARIANT', 'Pick what the product is.', false, '[{"value":"ORDINARY_NONMEDICATED","label":"Soap, toothpaste or other non-medicated item"},{"value":"OTC_MEDICINE","label":"Over-the-counter medicine with Drug Facts"},{"value":"FEMININE_HYGIENE","label":"Feminine hygiene product"}]'::jsonb),
    ('device_kind', 'Kind of device', 'CHOICE', null, 'VARIANT', 'Pick what fits best. Prescribed or medically qualifying devices need proof.', false, '[{"value":"QUALIFYING_EXEMPT_DEVICE","label":"Qualifying medical device"},{"value":"PRESCRIBED_ELIGIBLE_DEVICE","label":"Prescribed eligible device"},{"value":"NONQUALIFYING_CONSUMER_DEVICE","label":"Ordinary consumer device"}]'::jsonb),
    ('device_evidence', 'Proof the device qualifies', 'FILE', null, 'VARIANT', 'Upload the product listing, FDA clearance or the prescription rule that shows it qualifies.', true, '[]'::jsonb),
    ('publication_type', 'Type of publication', 'CHOICE', null, 'VARIANT', 'Pick what the publication is.', false, '[{"value":"ORDINARY_MAGAZINE_PERIODICAL","label":"Magazine or periodical"},{"value":"QUALIFYING_EXEMPT_NEWSPAPER_OR_OTHER","label":"Newspaper or other publication with a specific exemption"}]'::jsonb),
    ('publication_evidence', 'Proof of the exemption', 'FILE', null, 'VARIANT', 'Upload the page or notice that shows why it is exempt.', true, '[]'::jsonb),
    ('wellness_class', 'What this product is', 'CHOICE', null, 'VARIANT', 'Pick what the product is under its label.', false, '[{"value":"SUPPLEMENT","label":"Dietary supplement (Supplement Facts)"},{"value":"FOOD","label":"Food or food product"},{"value":"ORDINARY_GOODS","label":"Other wellness goods"}]'::jsonb),
    ('delivery_mode', 'How the course is delivered', 'CHOICE', null, 'VARIANT', 'Live classes taught by an instructor, or a recording or other digital deliverable.', false, '[{"value":"LIVE_INSTRUCTOR_LED","label":"Live, led by an instructor"},{"value":"RECORDED_OR_DIGITAL_DELIVERABLE","label":"Recorded or a digital file or access"}]'::jsonb),
    ('delivery_method', 'How the customer gets it', 'CHOICE', null, 'VARIANT', 'Download of a file, or online access only.', false, '[{"value":"DOWNLOAD","label":"Download"},{"value":"STREAM_OR_ACCESS","label":"Online access or streaming"}]'::jsonb),
    ('exemption_confirmed', 'Exemption confirmed by tax review', 'BOOLEAN', null, 'STAFF', 'Set only by our tax team after review. Sellers do not fill this in.', false, '[]'::jsonb),
    ('deliverable_kind', 'What the buyer receives', 'CHOICE', null, 'VARIANT', 'A file or artwork to keep, or only a personal service.', false, '[{"value":"DOWNLOADED_FILE","label":"A downloaded file, artwork or photo"},{"value":"PERSONAL_SERVICE_NO_DELIVERABLE","label":"A personal service with no file delivered"}]'::jsonb),
    ('output_kind', 'What the customer gets', 'CHOICE', null, 'VARIANT', 'Photos or prints and files to keep, or only the service.', false, '[{"value":"TAXABLE_PRINTS_OR_DIGITAL_DELIVERABLE","label":"Photos, prints or digital files"},{"value":"SERVICE_ONLY_NO_TAXABLE_DELIVERABLE","label":"Service only, nothing to keep"}]'::jsonb),
    ('admission_kind', 'Kind of event', 'CHOICE', null, 'VARIANT', 'Pick what fits the event. Exempt events need proof.', false, '[{"value":"TAXABLE_AMUSEMENT_ADMISSION","label":"Entertainment or amusement admission"},{"value":"NONTAXABLE_ADMISSION_OR_EXEMPT_EVENT","label":"Admission that is not taxable, or an exempt event"}]'::jsonb),
    ('admission_evidence', 'Proof the event is exempt', 'FILE', null, 'VARIANT', 'Upload the organiser''s exemption letter or event details.', true, '[]'::jsonb),
    ('fitness_kind', 'Class or membership', 'CHOICE', null, 'VARIANT', 'A class led by an instructor, or access to a gym or facility.', false, '[{"value":"INSTRUCTOR_LED_CLASS","label":"Class or training led by an instructor"},{"value":"MEMBERSHIP_OR_FACILITY_ACCESS","label":"Membership or facility access"}]'::jsonb),
    ('holiday_eligible', 'Eligible for a tax holiday or special exemption', 'BOOLEAN', null, 'VARIANT', 'Yes only if this item is listed for a legislated tax holiday or exemption. Our tax team checks this.', false, '[]'::jsonb),
    ('exemption_window_active', 'Sale date inside an exemption window', 'BOOLEAN', null, 'CONTEXT', 'Worked out by the system from the sale date and the exemption calendar; never typed by a person.', false, '[]'::jsonb),
    ('bundle_line_kind', 'How the bundle is itemised', 'CHOICE', null, 'VARIANT', 'Each item in a gift basket must be its own line with its own category and price.', false, '[{"value":"EXEMPT_FOOD_LINE_ITEMIZED","label":"Exempt food, listed as its own line"},{"value":"TAXABLE_GOODS_LINE_ITEMIZED","label":"Taxable goods, listed as their own line"},{"value":"UNITEMIZED_MIXED_BUNDLE","label":"Mixed items sold as one price, not itemised"}]'::jsonb),
    ('gift_card_event', 'Gift card transaction', 'CHOICE', null, 'CONTEXT', 'Set by the order system: the sale of the card, or its use to buy a taxable or an exempt item.', false, '[{"value":"SALE_MULTIPURPOSE_CARD","label":"Sale of a multipurpose card"},{"value":"REDEMPTION_TAXABLE_ITEM","label":"Used to buy a taxable item"},{"value":"REDEMPTION_EXEMPT_ITEM","label":"Used to buy an exempt item"}]'::jsonb);
